const item = $input.first().json;
const raw = item.body ?? item;
const data = raw.data ?? {};
const ORG = '11111111-1111-1111-1111-111111111111';
const INTENTS = new Set(['new_patient_inquiry','existing_patient','appointment_booking','appointment_reschedule','emergency','billing_insurance','general_question','other']);
const OUTCOMES = new Set(['booked','callback_requested','information_provided','transferred_to_staff','voicemail','no_action','lost']);

function collected(id) {
  const entry = data.analysis?.data_collection_results?.[id];
  if (entry == null) return null;
  const value = typeof entry === 'object' && entry !== null && 'value' in entry ? entry.value : entry;
  if (value == null) return null;
  const text = String(value).trim();
  return text || null;
}

function allowed(value, set) {
  return value && set.has(value) ? value : null;
}

function result(call, reason) {
  return [{ json: { ...call, skip: !call.phone, reason: call.phone ? null : reason } }];
}

if (raw.type === 'post_call_transcription') {
  const phoneCall = data.metadata?.phone_call ?? {};
  const dynamic = data.conversation_initiation_client_data?.dynamic_variables ?? {};
  const started = data.metadata?.start_time_unix_secs
    ? new Date(Number(data.metadata.start_time_unix_secs) * 1000).toISOString()
    : new Date().toISOString();
  const summary = data.analysis?.transcript_summary ? String(data.analysis.transcript_summary).trim() : null;
  const outcome = allowed(collected('outcome'), OUTCOMES);
  const lines = Array.isArray(data.transcript) ? data.transcript.flatMap((turn) => {
    const text = turn && turn.message ? String(turn.message).trim() : '';
    if (!text) return [];
    return [{ speaker: turn.role === 'agent' ? 'ai' : 'patient', timestamp_seconds: Math.round(Number(turn.time_in_call_secs) || 0), text }];
  }) : [];
  const transcript = lines.length || summary ? { lines, summary: summary || '', recommended_follow_up: outcome === 'callback_requested' ? 'Front desk should call back within 2 business hours.' : null } : null;
  return result({
    organization_id: dynamic.organization_id || ORG,
    direction: phoneCall.direction === 'outbound' || dynamic.direction === 'outbound' ? 'outbound' : 'inbound',
    caller_name: collected('caller_name') || dynamic.patient_name || dynamic.caller_name || 'Unknown Caller',
    phone: phoneCall.external_number || '',
    status: 'completed',
    intent: allowed(collected('intent'), INTENTS),
    outcome,
    duration_seconds: Math.round(Number(data.metadata?.call_duration_secs) || 0),
    started_at: started,
    notes: summary,
    ai_handled: true,
    transcript
  }, 'No caller phone number. A dashboard test chat does not include one.');
}

if (raw.type === 'call_initiation_failure') {
  const failureDynamic = data.conversation_initiation_client_data?.dynamic_variables ?? {};
  const body = data.metadata?.body ?? {};
  const inbound = failureDynamic.direction === 'inbound' || String(body.Direction || '').toLowerCase().includes('inbound');
  const phone = inbound
    ? (body.From || body.Caller || body.from_number || '')
    : (body.To || body.Called || body.to_number || '');
  return result({
    organization_id: failureDynamic.organization_id || ORG,
    direction: inbound ? 'inbound' : 'outbound',
    caller_name: failureDynamic.patient_name || 'Unknown Caller',
    phone,
    status: 'missed',
    intent: null,
    outcome: null,
    duration_seconds: 0,
    started_at: raw.event_timestamp ? new Date(Number(raw.event_timestamp) * 1000).toISOString() : new Date().toISOString(),
    notes: data.failure_reason ? `Call was not answered (${data.failure_reason}).` : 'Call was not answered.',
    ai_handled: false,
    transcript: null
  }, 'No phone number on the failed call.');
}

return [{ json: { skip: true, reason: 'Ignored event ' + (raw.type || 'unknown') + '.', phone: '' } }];
